}

sign=sign(list);

json={"sign":sign,"packageName":"com.lestory.jihua.an","time":time,"token":"","locale":"CN","osType":"2","book_id":result,"lang":"zh-hans","lang-app":"zh-Hans","ver":"2.1.3","product":1,"sysVer":"10"}
